from pathlib import Path
p=Path('outputs/index.html');s=p.read_text(encoding='utf-8')
css='''.combatActions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}.combatActions .control{min-height:78px}.escapeControls{display:grid;gap:10px;margin-top:14px}.escapeControls>p{margin:0;color:#a8bbc4;font-size:10px;line-height:1.6}.escapeDistances,.escapeDirs,.escapeButtons{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}.escapeDistances button,.escapeDirs button,.escapeButtons button{min-height:44px;padding:8px;font-size:10px}.escapeDirs{grid-template-columns:repeat(2,minmax(0,1fr))}.escapeDistances button.sel,.escapeDirs button.sel{border-color:var(--cyan);background:#123239;color:var(--cyan)}.escapeButtons{grid-template-columns:1fr 1fr}.escapeButtons .primary{background:#0f3a3b}.overlay#combatOverlay{background:#03091099}.arena-wrap .modal{max-height:calc(100% - 32px);overflow:auto}
+@media(max-width:560px){.combatActions{gap:6px}.combatActions .control{min-height:64px;padding:8px}.combatActions .control strong{font-size:15px}.escapeDistances button,.escapeDirs button,.escapeButtons button{min-height:48px;font-size:9px;padding:6px}.arena-wrap .modal{padding:16px;max-width:calc(100% - 24px)}}
+'''
s=s.replace('</style>',css.replace('\n+@media','\n@media')+'</style>',1)
# Escape direction can also be selected by tapping the arena itself.
old="function selectDirection(x,y){if(Math.abs(x)>Math.abs(y))moveDir={x:Math.sign(x),y:0};else if(y!==0)moveDir={x:0,y:Math.sign(y)};else return;document.querySelectorAll('[data-dir]').forEach(b=>{let [dx,dy]=b.dataset.dir.split(',').map(Number),yes=dx===moveDir.x&&dy===moveDir.y;b.classList.toggle('sel',yes);b.setAttribute('aria-pressed',String(yes))});$('#dirLabel').textContent=moveDir.y<0?'NORTH':moveDir.y>0?'SOUTH':moveDir.x<0?'WEST':'EAST';draw();if(state?.phase==='move')sendHost({type:'move',move:moveChoice,dir:moveDir})}"
new=old+"function selectEscapeDirection(x,y){if(Math.abs(x)>Math.abs(y))escapeDir={x:Math.sign(x),y:0};else if(y!==0)escapeDir={x:0,y:Math.sign(y)};else return;document.querySelectorAll('[data-escape-dir]').forEach(b=>{let [dx,dy]=b.dataset.escapeDir.split(',').map(Number),yes=dx===escapeDir.x&&dy===escapeDir.y;b.classList.toggle('sel',yes);b.setAttribute('aria-pressed',String(yes))});draw()}"
if old not in s: print('selectDirection function not found')
else:s=s.replace(old,new,1)
s=s.replace("if(state.phase==='move'&&p?.alive&&!p.contained){let r=cv.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;selectDirection(x-p.x,y-p.y);cv.focus()}", "if((state.phase==='move'&&p?.alive&&!p.contained)||(state.phase==='combat'&&escapeSelecting&&p?.alive)){let r=cv.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width,y=(e.clientY-r.top)*H/r.height;if(state.phase==='move')selectDirection(x-p.x,y-p.y);else selectEscapeDirection(x-p.x,y-p.y);cv.focus()}")
# Clear first-action bonuses when a new engagement starts.
s=s.replace("state.momentum=pair.initiator;state.ambush=pair.ambush;state.phase='combat';state.combatTurn=1;", "state.momentum=pair.initiator;state.ambush=pair.ambush;state.momentumUsed=null;state.ambushUsed=null;state.phase='combat';state.combatTurn=1;",1)
p.write_text(s,encoding='utf-8')
